//! Lab P32: instrument and robotics execution-integrity contracts.
use bioprism_foundation::{PRECLINICAL_BOUNDARY,RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize,Serialize};
use serde_json::{json,Value};
use std::collections::BTreeSet;
use thiserror::Error;
pub const BOUNDARY:&str=PRECLINICAL_BOUNDARY;
pub const CONTENT_TYPE:&str="application/vnd.aurora.lab.instrument-execution-integrity-card-1+json";
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct InstrumentAction4{pub action_id:String,pub instrument_id:String,pub effect:String,pub interlock:String,pub digest:String,pub evidence_state:String,pub local:bool,pub aggregate_only:bool}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct InstrumentExecutionRequest4{pub schema_version:String,pub request_id:String,pub purpose:String,pub actions:Vec<InstrumentAction4>,pub required_action_order:Vec<String>,pub replay_identity:String,pub signed_preflight:bool,pub human_authorized:bool,pub emergency_stop:bool,pub policy_allowed:bool,pub protected_closure:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub adversarial_events:Vec<String>,pub action_budget:usize,pub boundary:String}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct InstrumentExecutionArtifact4{pub artifact_id:String,pub content_type:String,pub content_hash:String,pub semantic_loss:Vec<String>,pub evidence_digests:Vec<String>,pub boundary:String}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct InstrumentExecutionCard7{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub request_id:String,pub purpose:String,pub disposition:String,pub action_order:Vec<String>,pub approved_order:Vec<String>,pub rejected_order:Vec<String>,pub unknown_order:Vec<String>,pub omitted_order:Vec<String>,pub interlock_order:Vec<String>,pub instrument_order:Vec<String>,pub effect_order:Vec<String>,pub replay_identity:String,pub closure_digest:String,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String,pub effect_receipts:Vec<String>,pub artifact:InstrumentExecutionArtifact4}
#[derive(Debug,Error)] pub enum InstrumentExecutionIntegrityError{#[error("instrument execution integrity input is invalid: {0}")] Invalid(String),#[error("instrument execution integrity digest failed: {0}")] Digest(String)}
fn digest(v:&str)->bool{v.len()==64&&v.bytes().all(|b|b.is_ascii_hexdigit())}fn canonical(v:&[String])->bool{v.windows(2).all(|w|w[0]<w[1])}fn invalid(v:impl Into<String>)->InstrumentExecutionIntegrityError{InstrumentExecutionIntegrityError::Invalid(v.into())}
pub fn manifest(feature_id:&str,contract_version:&str,scale:&str,mode:&str)->Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":feature_id,"version":contract_version,"owner_crate":"lab","consumers":["instrument gateway","robotics operator","protocol simulator","research workbench"],"behavior":format!("qualify instrument execution preflight at {scale} ({mode})"),"value":"prevents unauthorized or unsafe physical effects while preserving dry-run, interlock, emergency-stop, and compensation evidence","input_schema":"InstrumentExecutionRequest4@1","output_schema":"InstrumentExecutionCard7@1","effects":["emit:execution-card","retain:preflight-evidence","block:unsafe-physical-effect"],"permissions":["read:local-instrument-fixtures"],"determinism":"byte_stable","autonomy_tier":"A3","boundary":BOUNDARY})}
fn validate_card(c:&InstrumentExecutionCard7)->Result<(),InstrumentExecutionIntegrityError>{if c.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||c.feature_id.is_empty()||c.request_id.is_empty()||c.purpose.is_empty()||c.boundary!=BOUNDARY||c.artifact.boundary!=BOUNDARY||!c.raw_data_local||!c.aggregate_only||!digest(&c.replay_identity)||!digest(&c.closure_digest)||c.artifact.content_type!=CONTENT_TYPE||c.artifact.content_hash!=c.closure_digest{return Err(invalid("execution identity, locality, artifact, digest, or boundary is incomplete"));}for v in [&c.action_order,&c.approved_order,&c.rejected_order,&c.unknown_order,&c.omitted_order,&c.interlock_order,&c.instrument_order,&c.effect_order,&c.effect_receipts]{if !canonical(v){return Err(invalid("execution vectors are not canonical"));}}let ids=c.action_order.iter().collect::<BTreeSet<_>>();let states=c.approved_order.iter().chain(&c.rejected_order).chain(&c.unknown_order).chain(&c.omitted_order).collect::<Vec<_>>();if states.len()!=ids.len()||states.into_iter().collect::<BTreeSet<_>>()!=ids{return Err(invalid("action states do not partition actions"));}Ok(())}
pub fn qualify(q:&InstrumentExecutionRequest4,feature_id:&str,contract_version:&str,scale:&str,mode:&str)->Result<InstrumentExecutionCard7,InstrumentExecutionIntegrityError>{if q.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||q.request_id.trim().is_empty()||q.purpose.trim().is_empty()||q.actions.is_empty()||q.required_action_order.is_empty()||!canonical(&q.required_action_order)||!digest(&q.replay_identity)||q.boundary!=BOUNDARY||!q.raw_data_local||!q.aggregate_only||!canonical(&q.adversarial_events)||q.action_budget==0{return Err(invalid("execution identity, ordering, digest, locality, boundary, or budget is invalid"));}let mut rows=q.actions.clone();rows.sort_by(|a,b|a.action_id.cmp(&b.action_id));let mut seen=BTreeSet::new();let mut approved=BTreeSet::new();let mut rejected=BTreeSet::new();let mut unknown=BTreeSet::new();let mut omitted=BTreeSet::new();let mut interlocks=BTreeSet::new();let mut instruments=BTreeSet::new();let mut effects=BTreeSet::new();let mut evidence=BTreeSet::new();for a in &rows{if a.action_id.trim().is_empty()||!seen.insert(a.action_id.clone())||a.instrument_id.trim().is_empty()||a.effect.trim().is_empty()||a.interlock.trim().is_empty()||!digest(&a.digest)||a.evidence_state.trim().is_empty()||!a.local||!a.aggregate_only{return Err(invalid("action identity, instrument, effect, interlock, digest, evidence, or locality is invalid"));}interlocks.insert(format!("{}:{}",a.action_id,a.interlock));instruments.insert(format!("{}:{}",a.action_id,a.instrument_id));effects.insert(format!("{}:{}",a.action_id,a.effect));evidence.insert(a.digest.clone());if a.evidence_state=="unknown"||a.digest==q.replay_identity{unknown.insert(a.action_id.clone());}else if a.effect=="physical"&&!q.signed_preflight||a.effect=="physical"&&!q.human_authorized||a.effect=="physical"&&q.emergency_stop{rejected.insert(a.action_id.clone());}else if !q.required_action_order.contains(&a.action_id){omitted.insert(a.action_id.clone());}else{approved.insert(a.action_id.clone());}}let missing=q.required_action_order.iter().filter(|x|!seen.contains(*x)).cloned().collect::<Vec<_>>();let physical=rows.iter().any(|a|a.effect=="physical");let global=!q.policy_allowed||!q.protected_closure||!q.raw_data_local||!q.aggregate_only||!q.adversarial_events.is_empty()||rows.len()>q.action_budget||(physical&&(!q.signed_preflight||!q.human_authorized||q.emergency_stop));if global{omitted.extend(seen.iter().cloned());approved.clear();rejected.clear();unknown.clear();}let disposition=if global{"blocked"}else if !missing.is_empty()||!unknown.is_empty(){"unknown"}else if !rejected.is_empty()||!omitted.is_empty(){"partial"}else{"qualified"};let body=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":contract_version,"feature_id":feature_id,"request_id":q.request_id,"purpose":q.purpose,"disposition":disposition,"action_order":seen.iter().cloned().collect::<Vec<_>>()});let closure_digest=ContentHash::of_value(&body).map_err(|e|InstrumentExecutionIntegrityError::Digest(e.to_string()))?.to_string();let approved_order=approved.into_iter().collect::<Vec<_>>();let rejected_order=rejected.into_iter().collect::<Vec<_>>();let unknown_order=unknown.into_iter().collect::<Vec<_>>();let omitted_order=omitted.into_iter().collect::<Vec<_>>();let artifact=InstrumentExecutionArtifact4{artifact_id:format!("lab-execution:{}",q.request_id),content_type:CONTENT_TYPE.into(),content_hash:closure_digest.clone(),semantic_loss:omitted_order.clone(),evidence_digests:evidence.into_iter().collect(),boundary:BOUNDARY.into()};let c=InstrumentExecutionCard7{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:contract_version.into(),feature_id:feature_id.into(),request_id:q.request_id.clone(),purpose:q.purpose.clone(),disposition:disposition.into(),action_order:body["action_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),approved_order,rejected_order,unknown_order,omitted_order,interlock_order:interlocks.into_iter().collect(),instrument_order:instruments.into_iter().collect(),effect_order:effects.into_iter().collect(),replay_identity:q.replay_identity.clone(),closure_digest,raw_data_local:true,aggregate_only:true,boundary:BOUNDARY.into(),effect_receipts:if disposition=="qualified"{vec![format!("approve:preflight:{}",q.request_id)]}else{vec!["block:unsafe-physical-effect".into()]},artifact};validate_card(&c)?;let _=(scale,mode);Ok(c)}
